CREATE OR REPLACE FUNCTION public.sb_reset_class_progress(p_class uuid, p_teacher uuid, p_lesson integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids uuid[]; lessons integer[];
begin
